func:
// SITE SETTINGS of the SIH report daily tab (site name, dry run).
// In: the hourly tick (goes on only in the local hour runHourLocal of the
// site in 1.1 CONFIG) or the backfill {start, end}. Out: msg.payload = the
// site name for the site setup, msg.trigger = the payload of the inject.
var SITE_NAME = 'Hull';
// true = log row counts, write NO files. false = write the tables.
var DRY_RUN = true;
// Schedule: yesterday plus this many days before it.
var REBUILD_DAYS = 2;
// The source this tab builds. A line whose source (1.1 CONFIG: line
// reportSource, else site reportSource) is this one writes to <root>/report,
// any other to <root>/candidate/<source>.
var SOURCE = 'sih';

function stop(text) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: text
  });
  node.error(text);
  return null;
}

var shared = glob.get('cfg');
if (!shared) {
  return stop('global cfg is missing: deploy or run the Config tab first');
}
var matches = shared.sites.filter(function (s) {
  return s.name === SITE_NAME;
});
if (!matches.length) {
  return stop('site "' + SITE_NAME + '" is not in the CONFIG sites list');
}
var site = matches[0];
if (!site.assetIds.length) {
  return stop('site "' + SITE_NAME + '" has no lines in CONFIG');
}
if (!site.timeZone || site.dayStartLocal === undefined) {
  return stop('site "' + SITE_NAME + '" needs timeZone and dayStartLocal');
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// Local hour of the site now: standard offset plus EU summer time.
function localHour(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = site.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  var offset = site.utcHours + (summer ? 1 : 0);
  return new Date(ms + offset * 3600000).getUTCHours();
}

var p = msg.payload;
var backfill = !!(p && typeof p === 'object' && p.start && p.end);
if (!backfill && site.runHourLocal !== localHour(Date.now())) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'not due (runs at ' + site.runHourLocal + ':00 local)'
  });
  return null;
}

var cfg = Object.assign({}, shared);
cfg.site = site.name;
cfg.dayStartHour = site.dayStartHour;
cfg.dayStartLocal = site.dayStartLocal;
cfg.timeZone = site.timeZone;
cfg.utcHours = site.utcHours;
cfg.euSummer = site.euSummer;
cfg.assetIds = site.assetIds;
cfg.lines = site.lines;
cfg.siteSource = site.reportSource;
cfg.dryRun = DRY_RUN;
cfg.rebuildDays = REBUILD_DAYS;
cfg.source = SOURCE;
cfg.referenceFolder = shared.root + '/reference';
cfg.liveFolder = shared.root + '/report';
cfg.candidateFolder = shared.root + '/candidate/' + SOURCE;
flow.set('cfg', cfg);

node.status({
  fill: DRY_RUN ? 'yellow' : 'green',
  shape: 'dot',
  text: SITE_NAME + (DRY_RUN ? ' DRY RUN' : ' WRITE MODE')
});
msg.trigger = p;
msg.payload = site.name;
msg.allMachines = true;
msg.day = new Date().toISOString().slice(0, 10);
msg.mode = backfill ? 'backfill' : 'schedule';
return msg;

// Sets the Glidepaths folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'glidepaths';
msg.path = cfg.referenceFolder + '/glidepaths/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the target lookup of one site from its Glidepaths file.
// In: msg.payload = parsed rows (Site Name, Line, OEE Bucket, month columns).
// Stores flow context targets_<site>: machine-site -> month 01/MM/YYYY ->
// {oee, pdt, updt, b: {bucket: value}}. Out 2: a failed item for an empty file.
var BUCKETS = {
  '% OEE': 'oee',
  'Planned Downtime (Total)': 'pdt',
  'Unplanned Downtime (Total)': 'updt'
};
// The file starts with a byte order mark: it sits in the first column name.
function clean(row) {
  var out = {};
  Object.keys(row).forEach(function (column) {
    out[column.replace(/\uFEFF/g, '')] = row[column];
  });
  return out;
}

var rows = Array.isArray(msg.payload) ? msg.payload.map(clean) : [];
if (!rows.length || rows[0].Line === undefined) {
  msg.payload = {
    failed: 'glidepaths ' + msg.site + ': no Line column or rows'
  };
  return [null, msg];
}

var lookup = {};
var cells = 0;
rows.forEach(function (row) {
  if (!row.Line || !row['Site Name'] || !row['OEE Bucket']) {
    return;
  }
  var field = BUCKETS[row['OEE Bucket']];
  var key = row.Line + '-' + row['Site Name'];
  Object.keys(row).forEach(function (column) {
    var value = String(row[column]).trim();
    if (!/^\d{2}\/\d{2}\/\d{4}$/.test(column) || value === '') {
      return;
    }
    var number = Number(value);
    if (isNaN(number)) {
      return;
    }
    lookup[key] = lookup[key] || {};
    lookup[key][column] = lookup[key][column] || {};
    lookup[key][column].b = lookup[key][column].b || {};
    lookup[key][column].b[row['OEE Bucket']] = number;
    if (field) {
      lookup[key][column][field] = number;
    }
    cells++;
  });
});
flow.set('targets_' + msg.site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ': ' + cells + ' target values'
});
msg.payload = msg.site;
return [msg, null];

// Sets the folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var TYPE_FOLDER = 'machine_names';
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'machine names';
msg.path = cfg.referenceFolder + '/' + TYPE_FOLDER;
msg.path += '/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Machine lookup of one site from its Machine Names file. In: msg.payload =
// parsed rows; stores flow context machines_<Site>: MachineName -> Dept,
// Area, Product Type. Out 2: a failed item. Report filters per site, skipped
// with msg.allMachines (SIH flow: its Config lines choose the machines).
var RULES = {
  Hull: {
    dropNames: [
      'GT4 - Auto'
    ],
    keepDepts: [
      'Dries Pack',
      'Liquids Pack'
    ]
  },
  Nottingham: {
    keepAreas: [
      'SD Packing',
      'Strepsils Packing'
    ]
  },
  Weinheim: {},
  Mira: {}
};

var site = msg.site;
var rule = msg.allMachines ? {} : RULES[site] || {};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].MachineName === undefined) {
  msg.payload = {
    failed: 'machine names ' + site + ': no MachineName column or rows'
  };
  return [null, msg];
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function allowed(list, value) {
  return !list || list.indexOf(value) !== -1;
}

// A machine left out by the rules has no entry: its rows get empty Dept,
// Area and Product Type, as in the report.
var lookup = {};
var kept = 0;
rows.forEach(function (row) {
  var name = text(row.MachineName);
  var dept = text(row.Dept);
  var area = text(row.Area);
  var drop = !name ||
    (rule.dropNames && rule.dropNames.indexOf(name) !== -1) ||
    !allowed(rule.keepDepts, dept) ||
    !allowed(rule.keepAreas, area);
  if (drop) {
    return;
  }
  lookup[name] = {
    'Dept': dept,
    'Area': area,
    'Product Type': text(row['Product Type'])
  };
  kept++;
});
flow.set('machines_' + site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + kept + ' machines'
});
msg.payload = site;
return [msg, null];

// Sets the folder of the Shift Patterns file for the list objects node.
// In: the message of one site (msg.site stays). Out: msg.what and msg.path =
// eu_report/reference/shift_naming/site=All/, the file of all sites.
var cfg = flow.get('cfg');

msg.what = 'shift patterns';
msg.path = cfg.referenceFolder + '/shift_naming/site=All/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the shift lookup from the Shift Patterns file.
// In: msg.payload = parsed rows (ShiftName, Shift). Stores flow context
// shiftMap: raw shift name -> Shift. Out 2: a failed item for an empty file.
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length && rows[0].ShiftName === undefined) {
  // a byte order mark can sit in the first column name
  rows = rows.map(function (row) {
    return {
      ShiftName: row['\uFEFFShiftName'],
      Shift: row.Shift
    };
  });
}
if (!rows.length || rows[0].ShiftName === undefined) {
  msg.payload = {
    failed: 'shift patterns: no ShiftName column or rows'
  };
  return [null, msg];
}

var map = {};
rows.forEach(function (row) {
  if (row.ShiftName !== undefined) {
    map[row.ShiftName] = row.Shift === undefined ? null : row.Shift;
  }
});
flow.set('shiftMap', map);
node.status({
  fill: 'green',
  shape: 'dot',
  text: Object.keys(map).length + ' raw shift names'
});
msg.payload = msg.site;
return [msg, null];

// Hands the inject payload back after the site setup.
// In: the message of the site setup, msg.trigger = the payload of the inject.
// Out: msg.payload = that payload, for the day list.
return {
  payload: msg.trigger
};

// Builds the production days of the shift report (23 to 25 hours, from
// dayStartLocal o'clock local time). One message per day, oldest first.
// In: the schedule inject or the backfill {start, end}.
// Out: {topic: 'day', payload: 'YYYY-MM-DD', mode, dayFromMs, dayToMs}.
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
// The schedule builds the days that ended this many hours ago or more. The
// tab runs at runHourLocal of the site (1.1 CONFIG), so no grace is needed.
var GRACE_HOURS = 0;
var cfg = flow.get('cfg');
var p = msg.payload;
var days = [];
var mode;

function dayStr(ms) {
  return new Date(ms).toISOString().slice(0, 10);
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// UTC offset of the site in hours: the standard offset of its time zone
// plus one hour in EU summer time (from 1.1 CONFIG, via flow context cfg).
function offsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = !!cfg.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  return (cfg.utcHours || 0) + (summer ? 1 : 0);
}

// UTC instant of dayStartLocal o'clock on the local day that begins on the
// UTC date dayMs. Right for a start from 04:00 (checked in 1.1 CONFIG).
function startOf(dayMs) {
  var asUtc = dayMs + cfg.dayStartLocal * HOUR_MS;
  return asUtc - offsetHours(asUtc) * HOUR_MS;
}

if (p && typeof p === 'object' && p.start && p.end) {
  mode = 'backfill';
  var s = Date.parse(p.start + 'T00:00:00Z');
  var e = Date.parse(p.end + 'T00:00:00Z');
  if (isNaN(s) || isNaN(e) || e < s) {
    node.error(
      'Backfill needs {"start":"YYYY-MM-DD","end":"YYYY-MM-DD"} ' +
        'with start <= end',
      msg
    );
    return null;
  }
  for (var t = s; t <= e; t += DAY_MS) {
    days.push(t);
  }
} else {
  mode = 'schedule';
  var now = Date.now();
  // The latest day that ended at least GRACE_HOURS ago.
  var latest = Math.floor(now / DAY_MS) * DAY_MS;
  while (startOf(latest + DAY_MS) + GRACE_HOURS * HOUR_MS > now) {
    latest -= DAY_MS;
  }
  for (var i = cfg.rebuildDays; i >= 0; i--) {
    days.push(latest - i * DAY_MS);
  }
}

var text = mode + ': ' + days.length + ' day(s) ' + dayStr(days[0]);
if (days.length > 1) {
  text += ' .. ' + dayStr(days[days.length - 1]);
}
node.status({ fill: 'blue', shape: 'dot', text: text });
var runId = Date.now().toString(36) + '-';
runId += Math.floor(Math.random() * 1000000).toString(36);
var startedAt = new Date().toISOString();
var messages = days.map(function (d) {
  return {
    topic: 'day',
    payload: dayStr(d),
    mode: mode,
    runId: runId,
    startedAt: startedAt,
    dayFromMs: startOf(d),
    dayToMs: startOf(d + DAY_MS)
  };
});
return [messages];

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// queue writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'sih-hull';
var SITE_NAME = 'Hull';
var STEP = 'day list built';
var ACTION = 'queue';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Turns a failed item into a log line. In: msg.payload = {failed: text}
// (a file that was not found or empty). Out: the log line. Nothing is built
// for the site, so no table file is written for it in this run.
var line = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] FAILED, NOTHING WRITTEN: ' +
    msg.payload.failed
};
return line;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// running writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'sih-hull';
var SITE_NAME = 'Hull';
var STEP = 'DAY SETUP';
var ACTION = 'running';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Builds the token request. The next node is an http request node.
// In: a day message {payload: 'YYYY-MM-DD', mode}.
// Out: msg.method, msg.url, msg.headers (and a form body on xcelerator).
var cfg = flow.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.day = msg.payload;
msg.loadedAt = Date.now();
msg.method = 'POST';
msg.url = cfg.tokenUrl;
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
if (cfg.tokenForm) {
  msg.headers['Content-Type'] = 'application/x-www-form-urlencoded';
  msg.payload = 'grant_type=client_credentials';
} else {
  delete msg.payload;
}
return msg;

// Keeps the token and builds the OEE asset list request (isConfigured,
// isManual). In: the token response. Out 1: the request for the http node.
// Out 2: a log message when the token request failed.
var cfg = flow.get('cfg');
var token = msg.payload && msg.payload.access_token;

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !token) {
  var failed = 'FAILED, NOTHING WRITTEN: token request failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}
msg.token = token;
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Chooses the assets to read for the day.
// In: the OEE asset list. Out 1: msg.payload = [{id, isManual, name}] for
// the split node. Out 2: a log message when nothing can be read.
var cfg = flow.get('cfg');
var byId = {};
var skipped = [];
var targets = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
  var failed = 'FAILED, NOTHING WRITTEN: OEE asset list failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}

var oee = msg.payload;
oee.forEach(function (o) {
  byId[o.assetId] = o;
});
var ids = cfg.assetIds;
if (!ids || !ids.length) {
  ids = oee.map(function (o) {
    return o.assetId;
  });
}
ids.forEach(function (id) {
  var o = byId[id];
  if (!o) {
    skipped.push(String(id).slice(0, 6) + '... not an OEE asset');
    return;
  }
  if (o.isConfigured === false) {
    skipped.push(o.name + ' not configured');
    return;
  }
  targets.push({ id: id, isManual: o.isManual, name: o.name });
});
msg.planSkipped = skipped;

if (!targets.length) {
  var nothing = 'NOTHING TO WRITE (no assets to read)';
  if (skipped.length) {
    nothing += ' | skipped: ' + skipped.join('; ');
  }
  return [null, logMessage(nothing)];
}
msg.payload = targets;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: msg.day + ': ' + targets.length + ' asset(s)'
});
return [msg, null];

// Builds the Asset Management request for one asset (to get hierarchyPath).
// In: one asset {id, isManual, name} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.asset = msg.payload;
msg.method = 'GET';
msg.url = cfg.amBase + '/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/hal+json'
};
delete msg.payload;
return msg;

// Works out the asset hierarchy and builds the evaluateKPIs request.
// In: the Asset Management response. Out 1: the KPI request.
// Out 2: the asset result for the join when the asset failed or is excluded.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;

// Names are root first. Tenant layout: [0] tenant, [1] region, [2] site,
// [3] area, [4] line, [5] machine. GT4 has no machine, so it is the line.
function hierarchyFromNames(names) {
  return {
    asset_name: names[names.length - 1] || null,
    site: names[2] || null,
    area: names[3] || null,
    line: names[4] || null,
    machine: names[5] || null
  };
}

function toJoin(note) {
  msg.payload = {
    assetId: msg.asset.id,
    name: msg.asset.name,
    failed: note.failed || null,
    skipped: note.skipped || null,
    kpiRows: [],
    lossRows: []
  };
  return [null, msg];
}

var details = msg.payload;
if (msg.statusCode !== 200 || !details || !details.name) {
  return toJoin({
    failed: msg.asset.name + ': asset details failed, HTTP ' + msg.statusCode
  });
}

var names = (details.hierarchyPath || []).map(function (p) {
  return p.name;
});
names.push(details.name);
msg.h = hierarchyFromNames(names);
var excluded = cfg.excludeNames.indexOf(details.name) >= 0;
var parentExcluded = names.slice(0, -1).some(function (n) {
  return cfg.excludeAncestorNames.indexOf(n) >= 0;
});
if (excluded || parentExcluded) {
  return toJoin({ skipped: msg.h.asset_name + ' excluded' });
}

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}
msg.method = 'POST';
msg.url = cfg.oeeBase + '/expressions/evaluateKPIs';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  assetId: msg.asset.id,
  scope: {
    from: new Date(from).toISOString(),
    to: new Date(to).toISOString(),
    filter: [{ key: 'PRODUCT', value: [] }],
    recursive: false,
    groupedByDateTime: true
  }
};
return [msg, null];

// Sends the answer of a day evaluateKPIs call on, or to the hourly parts.
// In: the answer of the http request node. Out 1: the answer, to the check
// node. Out 2: HTTP 413 (the day is too big for one call): to the hourly
// parts, which ask the same KPIs hour by hour and merge them.
if (msg.statusCode === 413) {
  return [null, msg];
}
return [msg, null];

// Splits a day evaluateKPIs call that answered 413 into hourly calls.
// In: the 413 answer, msg.asset, msg.token, msg.dayFromMs, msg.dayToMs and
// msg.job (a product or order call) or none (the day call). Out: one request
// per hour of the day, all in one group (msg.parts) for the join.
var cfg = flow.get('cfg');
// The length of one part. The day window is split into parts this long.
var PART_HOURS = 1;
var HOUR_MS = 3600000;

// The filters of the original call: the product or order of msg.job (same
// as the value KPI request), else the plain day call.
function filters() {
  if (!msg.job) {
    return [{ key: 'PRODUCT', value: [] }];
  }
  function filterFor(key) {
    return {
      key: key,
      value: msg.job.key === key ? [msg.job.value] : []
    };
  }
  return [
    filterFor('PRODUCT'),
    filterFor('ORDER'),
    { key: 'SHIFT', value: [] }
  ];
}

var windows = [];
for (var t = msg.dayFromMs; t < msg.dayToMs; t += PART_HOURS * HOUR_MS) {
  windows.push([t, Math.min(t + PART_HOURS * HOUR_MS, msg.dayToMs)]);
}

// The day join of the flow uses msg.parts too: keep it aside.
msg.dayParts = msg.parts;
var group = msg.asset.id + '|' + msg.day + '|' + Date.now() + '|';
group += Math.floor(Math.random() * 1000000);
delete msg.payload;
var out = windows.map(function (w, index) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.method = 'POST';
  copy.url = cfg.oeeBase + '/expressions/evaluateKPIs';
  copy.headers = {
    'Authorization': 'Bearer ' + msg.token,
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
  copy.payload = {
    assetId: msg.asset.id,
    scope: {
      from: new Date(w[0]).toISOString(),
      to: new Date(w[1]).toISOString(),
      filter: filters(),
      recursive: false,
      groupedByDateTime: true
    }
  };
  copy.parts = {
    id: group,
    index: index,
    count: windows.length,
    type: 'array'
  };
  return copy;
});
node.status({
  fill: 'yellow',
  shape: 'dot',
  text: msg.asset.name + ': 413, ' + out.length + ' hourly parts'
});
return [out];

// Packs the answer of one hourly evaluateKPIs call with its status code, so
// the join that follows keeps both.
// In: the answer of the http request node. Out: msg.payload = {statusCode,
// body}.
msg.payload = {
  statusCode: msg.statusCode,
  body: msg.payload
};
return msg;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// part-done writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'sih-hull';
var SITE_NAME = 'Hull';
var STEP = 'KPI hourly parts';
var ACTION = 'part-done';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Merges the hourly evaluateKPIs answers into one answer of the whole day,
// the same shape as the day call (results with their hourly groups).
// In: msg.payload = [{statusCode, body}] in hour order (join). Out: the day
// answer with msg.statusCode, to the same check node as the day call.
var parts = Array.isArray(msg.payload) ? msg.payload : [];

// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(body) {
  var list = body && (body.errors || (body.data && body.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(body).slice(0, 200);
}

// The day join of the flow gets its msg.parts back.
if (msg.dayParts === undefined) {
  delete msg.parts;
} else {
  msg.parts = msg.dayParts;
}
delete msg.dayParts;

var bad = parts.filter(function (p) {
  return !p || p.statusCode !== 200 || !p.body || typeof p.body !== 'object';
})[0];
if (bad || !parts.length) {
  msg.statusCode = bad ? bad.statusCode : 413;
  var text = 'also on 1 h windows: ';
  text += bad ? apiMessage(bad.body) : 'no hourly answer';
  msg.payload = {
    errors: [
      {
        message: text
      }
    ]
  };
  return msg;
}

// Step 1: the groups of every KPI, in the order the hours came.
var byName = {};
var order = [];
parts.forEach(function (p) {
  (p.body.results || []).forEach(function (r) {
    if (!byName[r.name]) {
      byName[r.name] = {
        name: r.name,
        groups: []
      };
      order.push(r.name);
    }
    byName[r.name].groups = byName[r.name].groups.concat(r.groups || []);
  });
});

// Step 2: the day answer. Unit and missing mappings of the first hour.
var first = parts[0].body;
var body = {
  productUnit: first.productUnit,
  results: order.map(function (name) {
    return byName[name];
  })
};
if (first.missingMapping) {
  body.missingMapping = first.missingMapping;
}
msg.statusCode = 200;
msg.payload = body;
if (!msg.job) {
  msg.kpiHourParts = parts.length;
}
return msg;

// Checks the evaluateKPIs response of one asset.
// In: the response. Out 1: the same message when it holds KPI results.
// Out 2: the asset result for the join when the call failed, the asset
// configuration is not finished or there is no data.
var name = msg.h.asset_name;
var body = msg.payload;

function toJoin(note) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: note.failed || null,
    skipped: note.skipped || null,
    kpiRows: [],
    lossRows: []
  };
  return [null, msg];
}

var notFinished = msg.statusCode === 400 &&
  /configuration not finished/i.test(JSON.stringify(body));
if (notFinished) {
  return toJoin({ skipped: name + ' configuration not finished' });
}
// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(payload) {
  var list = payload && (payload.errors ||
    (payload.data && payload.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(payload).slice(0, 200);
}

if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  var why = msg.statusCode === 200 ? '' : ': ' + apiMessage(body);
  return toJoin({
    failed: name + ': evaluateKPIs failed, HTTP ' + msg.statusCode + why
  });
}
if (!body.results || !body.results.length) {
  return toJoin({ skipped: name + ' no data' });
}
return [msg, null];

// Pivots the evaluateKPIs response to one entry per hour.
// In: the response (msg.payload.results, checked in node 3.3).
// Out: msg.hours = [{time, values}] oldest hour first, msg.kpiMeta and
// msg.unmapped (KPI names that have no column).

// KPI name in Insights Hub -> column name in fact_kpi.
var KPI_COLUMNS = {
  'Good parts': 'good_parts',
  'Total parts': 'total_parts',
  'Rejected parts': 'rejected_parts',
  'Connected rejected parts': 'connected_rejected_parts',
  'Manual rejected parts': 'manual_rejected_parts',
  'Theoretical output': 'theoretical_output',
  'Quality': 'quality',
  'Performance': 'performance',
  'Availability': 'availability',
  'OEE': 'oee',
  'TEEP': 'teep',
  'Total time': 'total_time_ms',
  'Planned stops': 'planned_stops_ms',
  'Planned stop from shift plan': 'planned_stop_shift_plan_ms',
  'Operational time': 'operational_time_ms',
  'Net production time': 'net_production_time_ms',
  'Net operational time': 'net_operational_time_ms',
  'Used operational time': 'used_operational_time_ms',
  'Availability losses': 'availability_losses_ms',
  'Availability loss (occurrence)': 'availability_loss_count',
  'Performance losses': 'performance_losses_ms',
  'Quality losses': 'quality_losses_ms',
  'MTTR': 'mttr_ms',
  'MTBF': 'mtbf_ms',
  'Downtime (duration)': 'downtime_ms',
  'Downtimes (occurrence)': 'downtime_count',
  'Micro stops (duration)': 'micro_stops_ms',
  'Micro stops (occurrence)': 'micro_stops_count',
  'Macro stops (duration)': 'macro_stops_ms',
  'Macro stops (occurrence)': 'macro_stops_count'
};
// Columns that are rounded to whole numbers. All others keep their decimals.
var INT_COLUMNS = [
  'total_time_ms',
  'planned_stops_ms',
  'planned_stop_shift_plan_ms',
  'operational_time_ms',
  'net_production_time_ms',
  'availability_losses_ms',
  'micro_stops_ms',
  'micro_stops_count',
  'macro_stops_ms'
];
// These columns come first in every row.
var RATIO_COLUMNS = [
  'oee',
  'teep',
  'availability',
  'performance',
  'quality'
];

function numOrNull(v) {
  if (v === null || v === undefined || v === '') {
    return null;
  }
  var n = Number(v);
  return isFinite(n) ? n : null;
}

// Collect the value of every KPI per hour.
var body = msg.payload;
var unmapped = [];
var byHour = {};
var times = [];
body.results.forEach(function (r) {
  var col = KPI_COLUMNS[r.name];
  if (!col) {
    if (unmapped.indexOf(r.name) < 0) {
      unmapped.push(r.name);
    }
    return;
  }
  (r.groups || []).forEach(function (g) {
    if (!byHour[g.time]) {
      byHour[g.time] = {};
      times.push(g.time);
    }
    byHour[g.time][col] = numOrNull(g.value);
  });
});

// One entry per hour with every column present (null when missing).
msg.hours = times.sort().map(function (t) {
  var hour = byHour[t];
  var values = {};
  RATIO_COLUMNS.forEach(function (c) {
    values[c] = hour[c] === undefined ? null : hour[c];
  });
  Object.keys(KPI_COLUMNS).forEach(function (k) {
    var c = KPI_COLUMNS[k];
    if (values.hasOwnProperty(c)) {
      return;
    }
    var x = hour[c] === undefined ? null : hour[c];
    var rounded = x !== null && INT_COLUMNS.indexOf(c) >= 0;
    values[c] = rounded ? Math.round(x) : x;
  });
  return { time: t, values: values };
});

var missing = null;
if (body.missingMapping && body.missingMapping.length) {
  missing = JSON.stringify(body.missingMapping);
}
msg.kpiMeta = {
  productUnit: body.productUnit || null,
  missingMapping: missing
};
msg.unmapped = unmapped;
delete msg.payload;
return msg;

// Builds the OEE config request of one asset (to get its calendar id).
// In: msg.asset and msg.token, after the KPI steps. msg.hours is kept.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets/' +
  encodeURIComponent(msg.asset.id) + '/config';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Saves the calendar and product collection ids, builds the events request.
// In: the OEE config response. Out 1: the calendarEvents request. Out 2:
// the asset result for the join when the config call failed or the asset
// has no calendar (no half days).
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var name = msg.h.asset_name;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  return [null, msg];
}

var config = msg.payload || {};
if (msg.statusCode !== 200) {
  return toJoin(name + ': asset config failed, HTTP ' + msg.statusCode);
}
if (!config.calendarId) {
  return toJoin(name + ': asset has no calendar id');
}

// The events that cover the production day D (D start hour to D+1).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}
msg.calendarId = config.calendarId;
msg.productCollectionId = config.productCollectionId || null;
msg.method = 'GET';
msg.url = cfg.oeeBase + '/calendars/' +
  encodeURIComponent(config.calendarId) + '/calendarEvents' +
  '?from=' + new Date(from).toISOString() +
  '&to=' + new Date(to).toISOString();
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Turns the calendar events into shift rules.
// In: the calendarEvents response. Out 1: msg.shiftRules = [{name, freq,
// interval, start, until, duration}] (epoch ms, null when open ended).
// Out 2: the asset result for the join when the call failed.
var name = msg.h.asset_name;
var events = msg.payload && msg.payload.calendarEvents;

if (msg.statusCode !== 200 || !Array.isArray(events)) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: name + ': calendar events failed, HTTP ' + msg.statusCode,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  return [null, msg];
}

// Date text to epoch ms, null when missing or not a date.
function toMs(text) {
  var ms = Date.parse(text);
  return isNaN(ms) ? null : ms;
}

// An event without a recurrence object gets freq null and never matches.
msg.shiftRules = events.map(function (e) {
  var rule = e.rrule;
  if (!rule || typeof rule !== 'object') {
    rule = {};
  }
  return {
    name: e.name || null,
    freq: rule.freq || null,
    interval: rule.interval || null,
    start: toMs(rule.dtstart),
    until: toMs(rule.until),
    duration: Math.round(Number(e.duration))
  };
});
delete msg.payload;
return [msg, null];

// Builds the filterValues request: the products and orders of the day.
// In: msg.asset, msg.token and msg.day after the shift steps.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}
var url = cfg.oeeBase + '/assets/';
url += encodeURIComponent(msg.asset.id) + '/filterValues';
url += '?from=' + new Date(from).toISOString();
url += '&to=' + new Date(to).toISOString();

msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Reads the filterValues answer and asks for the product list.
// In: the filterValues response. Out 1: the product list request. Out 2:
// no product collection, go on. Out 3: no product or order that day.
// Out 4: the asset result for the join when the call failed.
var cfg = flow.get('cfg');
var name = msg.h.asset_name;
// More values than this in one day fail the asset (one KPI call each).
var MAX_VALUES = 30;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, null, null, msg];
}

// The values of one filter key, text only, every value once.
function valuesOf(list, key) {
  var found = list.filter(function (f) {
    return f.key === key;
  })[0];
  var seen = [];
  ((found && found.value) || []).forEach(function (v) {
    var text = String(v);
    if (text !== '' && seen.indexOf(text) < 0) {
      seen.push(text);
    }
  });
  return seen;
}

var body = msg.payload;
if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  return toJoin(name + ': filterValues failed, HTTP ' + msg.statusCode);
}
var list = body.filterValues || [];
var products = valuesOf(list, 'product');
var orders = valuesOf(list, 'order');
if (products.length > MAX_VALUES || orders.length > MAX_VALUES) {
  return toJoin(name + ': more than ' + MAX_VALUES + ' products or orders');
}
msg.values = {
  products: products,
  orders: orders
};
delete msg.payload;
if (!products.length && !orders.length) {
  return [null, null, msg, null];
}
if (!msg.productCollectionId) {
  msg.productsCalled = false;
  return [null, msg, null, null];
}

msg.productsCalled = true;
var url = cfg.oeeBase + '/productCollections/';
url += encodeURIComponent(msg.productCollectionId) + '/products';
msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
return [msg, null, null, null];

// Keeps the products of the day and sends one message per product and
// per order. In: the product list response (or none). Out 1: one message
// per value. Out 2: nothing to ask. Out 3: asset result for the join.
var MIN_PER = {
  SECOND: 60,
  MINUTE: 1,
  HOUR: 1 / 60,
  DAY: 1 / 1440
};
var name = msg.h.asset_name;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, null, msg];
}

// Parts per minute of a product, null when the interval is not known.
function perMinute(p) {
  var factor = MIN_PER[String(p.designSpeedInterval).toUpperCase()];
  var value = Number(p.designSpeedValue);
  if (factor === undefined || !isFinite(value) || p.designSpeedValue === null) {
    return null;
  }
  return value * factor;
}

// Step 1: keep the master data of the products that ran that day.
var wanted = msg.values.products;
msg.productList = [];
if (msg.productsCalled) {
  var body = msg.payload;
  if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
    return toJoin(name + ': product list failed, HTTP ' + msg.statusCode);
  }
  var all = Array.isArray(body) ? body : body.products || [];
  all.forEach(function (p) {
    if (wanted.indexOf(String(p.name)) < 0) {
      return;
    }
    msg.productList.push({
      name: String(p.name),
      code: p.code ? String(p.code) : null,
      description: p.description ? String(p.description) : null,
      perMinute: perMinute(p)
    });
  });
}
delete msg.payload;
delete msg.productsCalled;

// Step 2: one job per product and per order.
var jobs = [];
msg.values.products.forEach(function (v) {
  jobs.push({ key: 'PRODUCT', value: v });
});
msg.values.orders.forEach(function (v) {
  jobs.push({ key: 'ORDER', value: v });
});
if (!jobs.length) {
  return [null, msg, null];
}

// Step 3: one message per job, in one group (msg.parts) for the join of
// 6.4. The day join uses msg.parts too: keep it aside in msg.assetParts.
var group = msg.asset.id + '|' + msg.day + '|' + Date.now() + '|';
group += Math.floor(Math.random() * 1000000);
msg.assetParts = msg.parts;
var out = jobs.map(function (job, index) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.job = job;
  copy.parts = {
    id: group,
    index: index,
    count: jobs.length,
    type: 'array'
  };
  return copy;
});
return [out, null, null];

// Builds the evaluateKPIs request of ONE product or order of the day.
// In: msg.job = {key: PRODUCT or ORDER, value}, msg.asset, msg.day.
// Out: the same POST as 3.2, filtered on that value, hourly.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}

function filterFor(key) {
  return { key: key, value: msg.job.key === key ? [msg.job.value] : [] };
}

msg.method = 'POST';
msg.url = cfg.oeeBase + '/expressions/evaluateKPIs';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  assetId: msg.asset.id,
  scope: {
    from: new Date(from).toISOString(),
    to: new Date(to).toISOString(),
    filter: [
      filterFor('PRODUCT'),
      filterFor('ORDER'),
      { key: 'SHIFT', value: [] }
    ],
    recursive: false,
    groupedByDateTime: true
  }
};
return msg;

// Sends the answer of a day evaluateKPIs call on, or to the hourly parts.
// In: the answer of the http request node. Out 1: the answer, to the check
// node. Out 2: HTTP 413 (the day is too big for one call): to the hourly
// parts, which ask the same KPIs hour by hour and merge them.
if (msg.statusCode === 413) {
  return [null, msg];
}
return [msg, null];

// Splits a day evaluateKPIs call that answered 413 into hourly calls.
// In: the 413 answer, msg.asset, msg.token, msg.dayFromMs, msg.dayToMs and
// msg.job (a product or order call) or none (the day call). Out: one request
// per hour of the day, all in one group (msg.parts) for the join.
var cfg = flow.get('cfg');
// The length of one part. The day window is split into parts this long.
var PART_HOURS = 1;
var HOUR_MS = 3600000;

// The filters of the original call: the product or order of msg.job (same
// as the value KPI request), else the plain day call.
function filters() {
  if (!msg.job) {
    return [{ key: 'PRODUCT', value: [] }];
  }
  function filterFor(key) {
    return {
      key: key,
      value: msg.job.key === key ? [msg.job.value] : []
    };
  }
  return [
    filterFor('PRODUCT'),
    filterFor('ORDER'),
    { key: 'SHIFT', value: [] }
  ];
}

var windows = [];
for (var t = msg.dayFromMs; t < msg.dayToMs; t += PART_HOURS * HOUR_MS) {
  windows.push([t, Math.min(t + PART_HOURS * HOUR_MS, msg.dayToMs)]);
}

// The day join of the flow uses msg.parts too: keep it aside.
msg.dayParts = msg.parts;
var group = msg.asset.id + '|' + msg.day + '|' + Date.now() + '|';
group += Math.floor(Math.random() * 1000000);
delete msg.payload;
var out = windows.map(function (w, index) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.method = 'POST';
  copy.url = cfg.oeeBase + '/expressions/evaluateKPIs';
  copy.headers = {
    'Authorization': 'Bearer ' + msg.token,
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
  copy.payload = {
    assetId: msg.asset.id,
    scope: {
      from: new Date(w[0]).toISOString(),
      to: new Date(w[1]).toISOString(),
      filter: filters(),
      recursive: false,
      groupedByDateTime: true
    }
  };
  copy.parts = {
    id: group,
    index: index,
    count: windows.length,
    type: 'array'
  };
  return copy;
});
node.status({
  fill: 'yellow',
  shape: 'dot',
  text: msg.asset.name + ': 413, ' + out.length + ' hourly parts'
});
return [out];

// Packs the answer of one hourly evaluateKPIs call with its status code, so
// the join that follows keeps both.
// In: the answer of the http request node. Out: msg.payload = {statusCode,
// body}.
msg.payload = {
  statusCode: msg.statusCode,
  body: msg.payload
};
return msg;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// part-done writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'sih-hull';
var SITE_NAME = 'Hull';
var STEP = 'VALUE hourly parts';
var ACTION = 'part-done';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Merges the hourly evaluateKPIs answers into one answer of the whole day,
// the same shape as the day call (results with their hourly groups).
// In: msg.payload = [{statusCode, body}] in hour order (join). Out: the day
// answer with msg.statusCode, to the same check node as the day call.
var parts = Array.isArray(msg.payload) ? msg.payload : [];

// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(body) {
  var list = body && (body.errors || (body.data && body.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(body).slice(0, 200);
}

// The day join of the flow gets its msg.parts back.
if (msg.dayParts === undefined) {
  delete msg.parts;
} else {
  msg.parts = msg.dayParts;
}
delete msg.dayParts;

var bad = parts.filter(function (p) {
  return !p || p.statusCode !== 200 || !p.body || typeof p.body !== 'object';
})[0];
if (bad || !parts.length) {
  msg.statusCode = bad ? bad.statusCode : 413;
  var text = 'also on 1 h windows: ';
  text += bad ? apiMessage(bad.body) : 'no hourly answer';
  msg.payload = {
    errors: [
      {
        message: text
      }
    ]
  };
  return msg;
}

// Step 1: the groups of every KPI, in the order the hours came.
var byName = {};
var order = [];
parts.forEach(function (p) {
  (p.body.results || []).forEach(function (r) {
    if (!byName[r.name]) {
      byName[r.name] = {
        name: r.name,
        groups: []
      };
      order.push(r.name);
    }
    byName[r.name].groups = byName[r.name].groups.concat(r.groups || []);
  });
});

// Step 2: the day answer. Unit and missing mappings of the first hour.
var first = parts[0].body;
var body = {
  productUnit: first.productUnit,
  results: order.map(function (name) {
    return byName[name];
  })
};
if (first.missingMapping) {
  body.missingMapping = first.missingMapping;
}
msg.statusCode = 200;
msg.payload = body;
if (!msg.job) {
  msg.kpiHourParts = parts.length;
}
return msg;

// Packs the answer of one product or order call for the join of 6.4.
// In: one filtered evaluateKPIs response (msg.job, msg.parts of the value
// group). Out: msg.payload = {key, value, failed, hours}: the hours (ms)
// that have parts, or the failure text.

// An hour belongs to the value when it has parts (total, else good).
function partsOf(results) {
  var wanted = ['Total parts', 'Good parts'];
  var found = null;
  wanted.forEach(function (n) {
    (results || []).forEach(function (r) {
      if (r.name === n && !found) {
        found = r;
      }
    });
  });
  return found;
}

var label = msg.job.key + ' ' + msg.job.value;
var body = msg.payload;
var packed = {
  key: msg.job.key,
  value: msg.job.value,
  failed: null,
  hours: []
};
if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  packed.failed = label + ' HTTP ' + msg.statusCode;
} else {
  var parts = partsOf(body.results);
  ((parts && parts.groups) || []).forEach(function (g) {
    if (Number(g.value) > 0) {
      packed.hours.push(Date.parse(g.time));
    }
  });
}
delete msg.job;
msg.payload = packed;
return msg;

// Collects the hours of every product and order of one asset and day.
// In: msg.payload = [{key, value, failed, hours}] from the join of 6.4.
// Out 1: the asset message with msg.valueHours. Out 2: the asset result
// for the day join when one of the calls failed.
var name = msg.h.asset_name;
var packs = Array.isArray(msg.payload) ? msg.payload : [];

// The day join gets its msg.parts back.
if (msg.assetParts === undefined) {
  delete msg.parts;
} else {
  msg.parts = msg.assetParts;
}
delete msg.assetParts;
delete msg.payload;

var hours = {
  PRODUCT: {},
  ORDER: {}
};
var failed = [];
packs.forEach(function (p) {
  if (p.failed) {
    failed.push(p.failed);
    return;
  }
  hours[p.key][p.value] = p.hours;
});

if (failed.length) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: name + ': value KPIs failed, ' + failed[0],
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, msg];
}
msg.valueHours = hours;
return [msg, null];

// Gives every hour of the day a product and an order.
// In: msg.hours, msg.valueHours, msg.productList (absent when no values).
// Out: hour.product and hour.order on every hour, and msg.hourInfo (hour
// start in ms -> product and order) for the stop rows.
var valueHours = msg.valueHours || { PRODUCT: {}, ORDER: {} };
var master = msg.productList || [];

// The value (a product name or an order) that has parts in this hour.
function valueAt(kind, ms) {
  var names = Object.keys(valueHours[kind]);
  var found = null;
  names.forEach(function (n) {
    if (found === null && valueHours[kind][n].indexOf(ms) >= 0) {
      found = n;
    }
  });
  return found;
}

// An hour without parts takes the value of the hour before it. Hours
// before the first value take the first value that follows.
function fill(list) {
  var last = null;
  list.forEach(function (item, i) {
    if (item === null) {
      list[i] = last;
    } else {
      last = item;
    }
  });
  var next = null;
  for (var i = list.length - 1; i >= 0; i--) {
    if (list[i] === null) {
      list[i] = next;
    } else {
      next = list[i];
    }
  }
  return list;
}

// Part name: the description when there is one, else the name. The key is
// the product code, else the name.
function productOf(productName) {
  if (productName === null) {
    return null;
  }
  var record = master.filter(function (p) {
    return p.name === productName;
  })[0];
  var rec = record || {};
  return {
    part_name: rec.description || productName,
    product_key: rec.code || productName,
    per_minute: rec.perMinute === undefined ? null : rec.perMinute
  };
}

var times = msg.hours.map(function (h) {
  return Date.parse(h.time);
});
var products = fill(times.map(function (ms) {
  return valueAt('PRODUCT', ms);
}));
var orders = fill(times.map(function (ms) {
  return valueAt('ORDER', ms);
}));

msg.hourInfo = {};
msg.hours.forEach(function (hour, i) {
  hour.product = productOf(products[i]);
  hour.order = orders[i];
  msg.hourInfo[String(times[i])] = {
    product: hour.product,
    order: hour.order
  };
});
delete msg.valueHours;
delete msg.productList;
delete msg.values;
return msg;

// Builds the Power BI rows of one asset and day from the hourly KPIs:
// pbi_plan_opt (per shift and product), pbi_time_utilisation (per day).
// In: msg.hours (with hour.product), msg.shiftRules, msg.h.
// Out: msg.planRows, msg.utilRows.
var MIN_MS = 60000;
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var MINUTES_PER_DAY = 1440;
var cfg = flow.get('cfg') || {};
var loadedAt = msg.loadedAt || Date.now();

// The shift of an instant: the event whose recurrence covers it, else null.
// The calendar rules hold local wall clock times: compare the local time.
function shiftOf(instant) {
  var ms = instant + offsetHours(instant) * HOUR_MS;
  var found = null;
  msg.shiftRules.forEach(function (rule) {
    if (found) {
      return;
    }
    var days = 0;
    if (rule.freq === 'DAILY') {
      days = 1;
    } else if (rule.freq === 'WEEKLY') {
      days = 7;
    }
    var until = rule.until === null ? Infinity : rule.until;
    if (!days || rule.start === null || ms < rule.start || ms > until) {
      return;
    }
    var step = days * rule.interval * DAY_MS;
    var occurrence = rule.start + Math.floor((ms - rule.start) / step) * step;
    if (ms < occurrence + rule.duration) {
      found = rule.name;
    }
  });
  return found;
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// UTC offset of the site in hours: the standard offset of its time zone
// plus one hour in EU summer time (from 1.1 CONFIG, via flow context cfg).
function offsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = !!cfg.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  return (cfg.utcHours || 0) + (summer ? 1 : 0);
}

// Adds a value to a sum. A sum with no value at all stays null.
function addTo(sum, key, value) {
  if (value === null || value === undefined) {
    return;
  }
  sum[key] = (sum[key] || 0) + value;
}

function minutes(ms) {
  return ms === null || ms === undefined ? null : ms / MIN_MS;
}

function sumOrNull(sum, key) {
  return sum[key] === undefined ? null : sum[key];
}

var groups = {};
var order = [];
msg.hours.forEach(function (hour) {
  var shift = shiftOf(Date.parse(hour.time));
  var product = hour.product || null;
  var key = String(shift) + '|' + String(product && product.product_key);
  var g = groups[key];
  if (!g) {
    g = {
      shift: shift,
      product: product,
      sum: {},
      hours: 0
    };
    groups[key] = g;
    order.push(key);
  }
  var v = hour.values;
  g.hours += 1;
  addTo(g.sum, 'good', v.good_parts);
  var planned = v.planned_stop_shift_plan_ms;
  if (v.total_time_ms !== null && planned !== null) {
    addTo(g.sum, 'total', minutes(v.total_time_ms - planned));
  }
  addTo(g.sum, 'opt', minutes(v.operational_time_ms));
  addTo(g.sum, 'oee', minutes(v.used_operational_time_ms));
  addTo(g.sum, 'down', minutes(v.downtime_ms));
});

// Parts that fit in a time at the design speed. Null without a speed.
function unitsOf(g, minutesKey) {
  var perMinute = g.product && g.product.per_minute;
  var time = g.sum[minutesKey];
  if (perMinute === null || perMinute === undefined || time === undefined) {
    return null;
  }
  return perMinute * time;
}

var daySum = {};
msg.planRows = order.map(function (key) {
  var g = groups[key];
  addTo(daySum, 'total', g.sum.total);
  addTo(daySum, 'opt', g.sum.opt);
  addTo(daySum, 'oee', g.sum.oee);
  return {
    site_name: msg.h.site,
    area_name: msg.h.area,
    machine_name: msg.h.asset_name,
    unique_machine_name: msg.asset.id,
    date: msg.day,
    shift_name: g.shift,
    part_name: g.product ? g.product.part_name : null,
    product_key: g.product ? g.product.product_key : null,
    good_parts: sumOrNull(g.sum, 'good'),
    capacity: unitsOf(g, 'opt'),
    downtime_units: unitsOf(g, 'down'),
    total_time: sumOrNull(g.sum, 'total'),
    planned_opt: sumOrNull(g.sum, 'opt'),
    oee_time: sumOrNull(g.sum, 'oee'),
    oee_target: null,
    pdt_target: null,
    updt_target: null,
    source_hours: g.hours,
    loaded_at: loadedAt
  };
});

msg.utilRows = [];
if (order.length) {
  msg.utilRows.push({
    site_name: msg.h.site,
    machine_name: msg.h.asset_name,
    unique_machine_name: msg.asset.id,
    date: msg.day,
    total_time_total: sumOrNull(daySum, 'total'),
    planned_opt_total: sumOrNull(daySum, 'opt'),
    oee_time_total: sumOrNull(daySum, 'oee'),
    all_time: MINUTES_PER_DAY,
    loaded_at: loadedAt
  });
}
delete msg.hours;
delete msg.kpiMeta;
return msg;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// running writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'sih-hull';
var SITE_NAME = 'Hull';
var STEP = 'ASSET STOPS';
var ACTION = 'running';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Builds the downtimeReasons request for one asset and one production day.
// In: msg.kpiRows (already built). Out: msg.method, msg.url and msg.headers
// for the http request node.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
// One page of 5000 holds every stop of a day (tested: 423 stops with
// size 1000). More than one page makes the day fail in node 4.2.
var PAGE_SIZE = 5000;

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}
var fromIso = new Date(from).toISOString();
var toIso = new Date(to).toISOString();
var query = '?from=' + encodeURIComponent(fromIso) +
  '&to=' + encodeURIComponent(toIso) +
  '&size=' + PAGE_SIZE + '&page=0';
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets/' +
  encodeURIComponent(msg.asset.id) + '/downtimeReasons' + query;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
return msg;

// Checks the downtimeReasons response of one asset.
// In: the response. Out 1: msg.stops = the list of stops.
// Out 2: the asset result for the join when the call failed or has more
// than one page. The KPI rows of the asset are dropped then (no half days).
var name = msg.h.asset_name;

function failedResult(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    kpiRows: [],
    lossRows: [],
    unmapped: msg.unmapped
  };
  delete msg.kpiRows;
  delete msg.unmapped;
  return [null, msg];
}

var body = msg.payload;
// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(payload) {
  var list = payload && (payload.errors ||
    (payload.data && payload.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(payload).slice(0, 200);
}

if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  var why = msg.statusCode === 200 ? '' : ': ' + apiMessage(body);
  return failedResult(
    name + ': downtimeReasons failed, HTTP ' + msg.statusCode + why
  );
}
if (body.page && body.page.totalPages > 1) {
  return failedResult(
    name + ': downtimeReasons has more than one page (' +
      body.page.totalElements + ' rows), raise PAGE_SIZE in node 4.1'
  );
}

msg.stops = (body._embedded && body._embedded.downtimeReasons) || [];
delete msg.payload;
return [msg, null];

// Builds the pbi_daily_losses rows of one asset: one row per stop.
// In: msg.stops, msg.shiftRules, msg.hourInfo, msg.h. Out: msg.lossRows and
// msg.droppedStops. Product and order come from the hour of the stop.
// Targets and volume total have no data yet and are null.
var MIN_MS = 60000;
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var cfg = flow.get('cfg');
// The reason a stop gets when nobody chose one.
var DEFAULT_REASON = 'Unplanned Downtime';
var BREAKDOWN_CATEGORY = 'Breakdown';
var loadedAt = msg.loadedAt || Date.now();
// The production day: the window of the day message (local day start,
// 23 to 25 hours), else dayStartHour UTC to the same hour the next day.
var midnight = Date.parse(msg.day + 'T00:00:00.000Z');
var fromMs = msg.dayFromMs || midnight + cfg.dayStartHour * HOUR_MS;
var toMs = msg.dayToMs || fromMs + DAY_MS;
var month = msg.day.slice(0, 7);

// The shift of an instant: the event whose recurrence covers it, else null.
// The calendar rules hold local wall clock times: compare the local time.
function shiftOf(instant) {
  var ms = instant + offsetHours(instant) * HOUR_MS;
  var found = null;
  msg.shiftRules.forEach(function (rule) {
    if (found) {
      return;
    }
    var days = 0;
    if (rule.freq === 'DAILY') {
      days = 1;
    } else if (rule.freq === 'WEEKLY') {
      days = 7;
    }
    var until = rule.until === null ? Infinity : rule.until;
    if (!days || rule.start === null || ms < rule.start || ms > until) {
      return;
    }
    var step = days * rule.interval * DAY_MS;
    var occurrence = rule.start + Math.floor((ms - rule.start) / step) * step;
    if (ms < occurrence + rule.duration) {
      found = rule.name;
    }
  });
  return found;
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// UTC offset of the site in hours: the standard offset of its time zone
// plus one hour in EU summer time (from 1.1 CONFIG, via flow context cfg).
function offsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = !!cfg.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  return (cfg.utcHours || 0) + (summer ? 1 : 0);
}

function numOrNull(v) {
  if (v === null || v === undefined || v === '') {
    return null;
  }
  var n = Number(v);
  return isFinite(n) ? n : null;
}

function lossGroup(category, reason) {
  if (cfg.plannedRoots.indexOf(category) >= 0) {
    return 'Planned Loss';
  }
  if (reason === DEFAULT_REASON) {
    return 'Not Logged';
  }
  return 'Unplanned Loss';
}

// Only stops that start inside the production day are kept.
var hourInfo = msg.hourInfo || {};
var lossRows = [];
var dropped = 0;
msg.stops.forEach(function (r) {
  var start = Date.parse(r.from);
  if (!(start >= fromMs && start < toMs)) {
    dropped++;
    return;
  }
  var parts = r.reasonFullPath ? String(r.reasonFullPath).split(' / ') : [];
  var category = parts.length > 1 ? parts[0] : null;
  var subgroup = parts.length > 2 ? parts[1] : null;
  var localMs = start + offsetHours(start) * HOUR_MS;
  var localIso = new Date(localMs).toISOString();
  var duration = numOrNull(r.duration);
  var minutes = duration === null ? null : Math.round(duration) / MIN_MS;
  var info = hourInfo[String(Math.floor(start / HOUR_MS) * HOUR_MS)] || {};
  var product = info.product || {};
  var perMinute = product.per_minute;
  var units = null;
  if (minutes !== null && perMinute !== null && perMinute !== undefined) {
    units = minutes * perMinute;
  }
  lossRows.push({
    site_name: msg.h.site,
    machine_name: msg.h.asset_name,
    unique_machine_name: msg.asset.id,
    date: localIso.slice(0, 10),
    time: localIso.slice(11, 19),
    shift_start_date: msg.day,
    shift_name: shiftOf(start),
    duration: minutes,
    loss_units: units,
    loss_lvl3_group: lossGroup(category, r.reason || null),
    loss_lvl3_sub_group: category,
    loss_lvl3_desc: r.reason || null,
    loss_final_level: r.reason || null,
    equipment: subgroup,
    breakdown_types: category === BREAKDOWN_CATEGORY ? subgroup : null,
    batch_id: info.order || null,
    comment_count: numOrNull(r.commentCount),
    part_name: product.part_name || null,
    product_key: product.product_key || null,
    loss_target_key: msg.h.line + '|' + category + '|' + localIso.slice(0, 7),
    value: null,
    target: null,
    volume_key: msg.h.line + '|' + localIso.slice(0, 7),
    volume_total: null,
    loaded_at: loadedAt
  });
});

msg.lossRows = lossRows;
msg.droppedStops = dropped;
delete msg.stops;
delete msg.hourInfo;
return msg;

// Builds the result of one asset and hands it to the join.
// In: msg.planRows, utilRows, lossRows, droppedStops and unmapped.
// Out: msg.payload = {assetId, name, failed, skipped, planRows, utilRows,
// lossRows, unmapped, outside, note}. The note is one line for the day log.
var name = msg.h.asset_name;

var total = msg.utilRows.reduce(function (sum, x) {
  return sum + (x.total_time_total || 0);
}, 0);
var note = name + ': ' + msg.planRows.length + ' plan rows, ' +
  msg.lossRows.length + ' stops, sum total_time ' +
  (total / 60).toFixed(2) + ' h';
if (msg.droppedStops) {
  note += ', ' + msg.droppedStops + ' stops outside the day ignored';
}
if (msg.kpiHourParts) {
  note += ', KPIs in ' + msg.kpiHourParts + ' hourly parts (413 on the day)';
}

msg.payload = {
  assetId: msg.asset.id,
  name: name,
  failed: null,
  skipped: null,
  planRows: msg.planRows,
  utilRows: msg.utilRows,
  lossRows: msg.lossRows,
  unmapped: msg.unmapped,
  outside: msg.droppedStops,
  note: note
};
delete msg.planRows;
delete msg.utilRows;
delete msg.lossRows;
delete msg.droppedStops;
delete msg.unmapped;
delete msg.shiftRules;
return msg;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// asset-done writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'sih-hull';
var SITE_NAME = 'Hull';
var STEP = 'JOIN & BUILD TABLES';
var ACTION = 'asset-done';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Collects the asset results that the join delivered.
// In: msg.payload = array of asset results. Out: msg.planRows, msg.utilRows,
// msg.lossRows and msg.summary = {failed, notes, skipped, unmapped}.
var results = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var failed = [];
var notes = [];
var skipped = (msg.planSkipped || []).slice();
var unmapped = [];
var planRows = [];
var utilRows = [];
var lossRows = [];

results.forEach(function (r) {
  if (!r) {
    return;
  }
  if (r.failed) {
    failed.push(r.failed);
  }
  if (r.skipped) {
    skipped.push(r.skipped);
  }
  if (r.note) {
    notes.push(r.note);
  }
  (r.unmapped || []).forEach(function (u) {
    if (unmapped.indexOf(u) < 0) {
      unmapped.push(u);
    }
  });
  planRows = planRows.concat(r.planRows || []);
  utilRows = utilRows.concat(r.utilRows || []);
  lossRows = lossRows.concat(r.lossRows || []);
});

msg.summary = {
  failed: failed,
  notes: notes,
  skipped: skipped,
  unmapped: unmapped
};
msg.planRows = planRows;
msg.utilRows = utilRows;
msg.lossRows = lossRows;
delete msg.payload;
delete msg.planSkipped;
return msg;

// Turns the SIH rows of the day into the report columns of Plan_OPT_EU,
// Time_Utilisation_EU and Daily_Losses_EU. In: msg.planRows, utilRows,
// lossRows; flow context targets_, machines_, shiftMap. Out: msg.tables =
// {table: [{out: folder, rows}]} and notes in msg.summary.notes.
var DATA_SOURCE = 'SIH';
// Shift names of the report: a SIH shift with one of these names is kept.
var REPORT_SHIFTS = [
  'Red',
  'Green',
  'Gold',
  'Blue',
  'Day',
  'Night',
  'Afternoon'
];
// The sub group of a stop without a category, as in the report.
var NO_SUB_GROUP = 'Not Logged';
var NO_EQUIPMENT = 'Unclassed';

var cfg = flow.get('cfg');
var site = cfg.site;
var targets = flow.get('targets_' + site) || {};
var machines = flow.get('machines_' + site) || {};
var shiftMap = flow.get('shiftMap') || {};
var lineById = {};
cfg.lines.forEach(function (line) {
  lineById[line.id] = line;
});
var noLine = {};
var noShift = {};
var noMachine = {};

// Days since 1970-01-01 of a date text YYYY-MM-DD (a DATE column value).
function dayNumber(text) {
  var y = Number(text.slice(0, 4));
  var m = Number(text.slice(5, 7));
  var d = Number(text.slice(8, 10));
  return Date.UTC(y, m - 1, d) / 86400000;
}

// Milliseconds of the day of a time text HH:MM:SS (on 1970-01-01).
function timeOfDay(text) {
  var parts = /^(\d{2}):(\d{2}):(\d{2})/.exec(String(text));
  if (!parts) {
    return null;
  }
  var secs = Number(parts[1]) * 3600 + Number(parts[2]) * 60;
  return (secs + Number(parts[3])) * 1000;
}

function whole(value) {
  return value === null || value === undefined ? null : Math.floor(value);
}

function rounded(value) {
  return value === null || value === undefined ? null : Math.round(value);
}

// The target as text with a decimal point, like the report (15.0, 3.9).
function valueText(number) {
  if (number === null) {
    return null;
  }
  return Number.isInteger(number) ? number + '.0' : String(number);
}

// The report machine of an asset: its Config line, else the SIH name.
function machineOf(row) {
  var line = lineById[row.unique_machine_name];
  if (!line) {
    noLine[row.machine_name] = true;
  }
  var name = line ? line.report : row.machine_name;
  var source = line && line.reportSource ? line.reportSource :
    cfg.siteSource;
  return {
    name: name,
    unique: name + '-' + site,
    out: source === cfg.source ? cfg.liveFolder : cfg.candidateFolder
  };
}

function shiftOf(name) {
  if (name === null || name === undefined) {
    return null;
  }
  if (REPORT_SHIFTS.indexOf(name) !== -1) {
    return name;
  }
  if (shiftMap.hasOwnProperty(name)) {
    return shiftMap[name];
  }
  noShift[name] = true;
  return name;
}

// Dept, Area, Product Type of the machine and the source.
function addMachine(row, name) {
  var info = machines[name];
  if (!info) {
    noMachine[name] = true;
  }
  row['Dept'] = info ? info.Dept : null;
  row['Area'] = info ? info.Area : null;
  row['Product Type'] = info ? info['Product Type'] : null;
  row['Data Source'] = DATA_SOURCE;
  return row;
}

function monthText(day) {
  return '01/' + day.slice(5, 7) + '/' + day.slice(0, 4);
}

// Rows grouped by output folder: [{out, rows}].
function byFolder(list) {
  var groups = {};
  var order = [];
  list.forEach(function (item) {
    if (!groups[item.out]) {
      groups[item.out] = [];
      order.push(item.out);
    }
    groups[item.out].push(item.row);
  });
  return order.map(function (out) {
    return {
      out: out,
      rows: groups[out]
    };
  });
}

var capacity = {};
var plan = msg.planRows.map(function (r) {
  var m = machineOf(r);
  var target = (targets[m.unique] || {})[monthText(r.date)] || {};
  var part = r.part_name;
  if (r.capacity !== null) {
    capacity[m.name] = (capacity[m.name] || 0) + r.capacity;
  }
  var row = {
    'Date': dayNumber(r.date),
    'AreaName': null,
    'MachineName': m.name,
    'ShiftName': shiftOf(r.shift_name),
    'PartName': part,
    'Good Parts': rounded(r.good_parts),
    'Capacity': r.capacity,
    'Total Time': whole(r.total_time),
    'Planned OpT': whole(r.planned_opt),
    'OEE Time': whole(r.oee_time),
    'Downtime Units': r.downtime_units,
    'SiteName': site,
    'Unique Machine Name': m.unique,
    'Product Key': m.unique + ' ' + (part || ''),
    'UPDT Target': target.updt === undefined ? null : target.updt,
    'PDT Target': target.pdt === undefined ? null : target.pdt,
    'OEE Target': target.oee === undefined ? null : target.oee
  };
  addMachine(row, m.name);
  row['source_hours'] = r.source_hours;
  row['loaded_at'] = r.loaded_at;
  return {
    out: m.out,
    row: row
  };
});

var util = msg.utilRows.map(function (r) {
  var m = machineOf(r);
  var row = {
    'Date': dayNumber(r.date),
    'MachineName': m.name,
    'OEE Time Total': r.oee_time_total,
    'Total Time Total': r.total_time_total,
    'Planned OPT Total': r.planned_opt_total,
    'SiteName': site,
    'Unique Machine Name': m.unique,
    'All Time': r.all_time
  };
  addMachine(row, m.name);
  row['loaded_at'] = r.loaded_at;
  return {
    out: m.out,
    row: row
  };
});

var loss = msg.lossRows.map(function (r) {
  var m = machineOf(r);
  var sub = r.loss_lvl3_sub_group || NO_SUB_GROUP;
  var group = r.loss_lvl3_group;
  var desc = r.loss_lvl3_desc;
  var day = r.shift_start_date;
  var daily = day.slice(8, 10) + '/' + day.slice(5, 7) + '/' +
    day.slice(0, 4);
  var month = monthText(day);
  var target = (targets[m.unique] || {})[month];
  var value = target && target.b && target.b[sub] !== undefined ?
    target.b[sub] : null;
  var part = r.part_name;
  var shift = shiftOf(r.shift_name);
  var ms = r.duration === null ? null : Math.round(r.duration * 60000);
  var volumeKey = daily + ' ' + m.name + ' ' + group + ' ' + sub + ' ' +
    desc;
  var row = {
    'Date': dayNumber(r.date),
    'Time': timeOfDay(r.time),
    'MachineName': m.name,
    'PartName': part,
    'Shift Time': shift,
    'ShiftName': shift,
    'OEELossLvl3Group': group,
    'OEELossLvl3SubGroup': sub,
    'OEELossLvl3Desc': desc,
    'Duration': ms,
    'SiteName': site,
    'Unique Machine Name': m.unique,
    'Breakdown Types': r.breakdown_types,
    'ShiftStartDate': dayNumber(day),
    'Comment': null,
    'Product Key': m.unique + ' ' + (part || ''),
    'Volume Key': volumeKey,
    'Loss Units': r.loss_units,
    'Time in Mins': r.duration,
    'Equipment Loss Key': m.name + ' ' + desc,
    'Equipment': r.equipment || NO_EQUIPMENT,
    'Lvl 3 Loss Name': desc,
    'Loss Target Key': m.unique + ' ' + sub + ' ' + month,
    'Value': valueText(value),
    'Volume Total': capacity.hasOwnProperty(m.name) ?
      capacity[m.name] : null,
    'Loss Final Level': desc
  };
  addMachine(row, m.name);
  row['target'] = value === null ? null : value / 100;
  row['batch_id'] = r.batch_id;
  row['comment_count'] = r.comment_count;
  row['loaded_at'] = r.loaded_at;
  return {
    out: m.out,
    row: row
  };
});

msg.tables = {
  Plan_OPT_EU: byFolder(plan),
  Time_Utilisation_EU: byFolder(util),
  Daily_Losses_EU: byFolder(loss)
};
var notes = [];
if (Object.keys(noLine).length) {
  notes.push('not a CONFIG line (SIH name kept): ' +
    Object.keys(noLine).join(' / '));
}
if (Object.keys(noShift).length) {
  notes.push('shift not in the report (SIH name kept): ' +
    Object.keys(noShift).join(' / '));
}
if (Object.keys(noMachine).length) {
  notes.push('not in Machine Names (no Dept, Area, Product Type): ' +
    Object.keys(noMachine).join(' / '));
}
msg.summary.notes = msg.summary.notes.concat(notes);
delete msg.planRows;
delete msg.utilRows;
delete msg.lossRows;
return msg;

// Decides what happens with the day.
// In: msg.tables {table: [{out, rows}]} and msg.summary. Out 1: the message
// goes on to the table messages (write). Out 2: a log line (failed, nothing
// to write, dry run). Any failed asset means nothing is written for the day.
var cfg = flow.get('cfg');
var day = msg.day;
var summary = msg.summary;
var notes = summary.notes.join(' | ');
var counts = {};
var sizes = Object.keys(msg.tables).map(function (table) {
  var parts = msg.tables[table].map(function (group) {
    return group.rows.length + ' rows to ' + group.out;
  });
  counts[table] = msg.tables[table].reduce(function (sum, group) {
    return sum + group.rows.length;
  }, 0);
  return table + ' ' + (parts.length ? parts.join(', ') : '0 rows');
}).join(', ');
var empty = !counts.Plan_OPT_EU && !counts.Daily_Losses_EU;

// Text added to the end of every log line.
var tail = '';
if (summary.skipped.length) {
  tail += ' | skipped: ' + summary.skipped.join('; ');
}
if (summary.unmapped.length) {
  tail += ' | KPI without column: ' + summary.unmapped.join(', ');
}

function logOnly(text) {
  var line = { topic: 'log', payload: day + ' [' + msg.mode + '] ' + text };
  return [null, line];
}

if (summary.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: day + ' FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + summary.failed.join(' | ') + tail
  );
}
if (empty) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: day + ' nothing to write'
  });
  return logOnly(notes + ' | NOTHING TO WRITE' + tail);
}
if (cfg.dryRun) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: day + ' dry run ' + counts.Plan_OPT_EU + '/' +
      counts.Daily_Losses_EU
  });
  return logOnly(notes + ' | DRY RUN: ' + sizes + tail);
}

msg.writeNote = notes + ' | WRITING ' + sizes + tail;
return [msg, null];

// Builds one message per table and output folder for the parquet nodes.
// In: msg.tables {table: [{out, rows}]} and msg.writeNote. Out 1:
// Plan_OPT_EU, out 2: Time_Utilisation_EU, out 3: Daily_Losses_EU (each a
// list, one message per folder), out 4: log line. No rows: no message.
var day = msg.day;

function table(name) {
  return msg.tables[name].filter(function (group) {
    return group.rows.length > 0;
  }).map(function (group) {
    return {
      topic: name,
      day: day,
      out: group.out,
      payload: group.rows
    };
  });
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: day + ' written'
});
var line = {
  topic: 'log',
  payload: day + ' [' + msg.mode + '] ' + msg.writeNote
};
return [
  table('Plan_OPT_EU'),
  table('Time_Utilisation_EU'),
  table('Daily_Losses_EU'),
  line
];

// Sets the file path of one table and production day: <out>/<table>/
// site=<Site>/<table>_<YYYY-MM-DD>_<source>.parquet. In: the parquet node
// output (msg.out, topic = table, day). Out: msg.path and msg.filename.
// The name is fixed per source and day: a rerun replaces only this file.
var cfg = flow.get('cfg');

msg.path = msg.out + '/' + msg.topic + '/site=' + cfg.site;
msg.path += '/' + msg.topic + '_' + msg.day + '_' + cfg.source;
msg.path += '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path of one table and production day: <out>/<table>/
// site=<Site>/<table>_<YYYY-MM-DD>_<source>.parquet. In: the parquet node
// output (msg.out, topic = table, day). Out: msg.path and msg.filename.
// The name is fixed per source and day: a rerun replaces only this file.
var cfg = flow.get('cfg');

msg.path = msg.out + '/' + msg.topic + '/site=' + cfg.site;
msg.path += '/' + msg.topic + '_' + msg.day + '_' + cfg.source;
msg.path += '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path of one table and production day: <out>/<table>/
// site=<Site>/<table>_<YYYY-MM-DD>_<source>.parquet. In: the parquet node
// output (msg.out, topic = table, day). Out: msg.path and msg.filename.
// The name is fixed per source and day: a rerun replaces only this file.
var cfg = flow.get('cfg');

msg.path = msg.out + '/' + msg.topic + '/site=' + cfg.site;
msg.path += '/' + msg.topic + '_' + msg.day + '_' + cfg.source;
msg.path += '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'sih-hull';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Maps one formatted run-log message to its day outcome.
// In: msg.line and the formatted log row in msg.payload.
// Out: the same message, unchanged.
var FLOW_NAME = 'sih-hull';
var SITE_NAME = 'Hull';
var KEY = 'runStatus_' + FLOW_NAME;
var KIND = 'day';
var status = glob.get(KEY);
var row = msg.payload || {};
var text = String(row.message || msg.line || '');
var day = row.production_day;
var now = new Date().toISOString();

if (status) {
  status.lastBeatAt = now;
  var item;
  if (KIND === 'month') {
    var monthMatch = /(?:^|\s)(\d{4}-\d{2})(?:\s|:)/.exec(text);
    var monthAt = monthMatch ? text.indexOf(monthMatch[1]) : -1;
    var site = row.site || text.slice(0, monthAt).trim();
    if (monthMatch && site) {
      item = status.months[monthMatch[1] + '|' + site];
      day = monthMatch[1] + '|' + site;
    }
  } else {
    item = status.days && status.days[day];
  }
  if (item) {
    if (/\bWRITING\b/.test(text)) {
      item.state = 'written';
      item.detail = '';
    } else if (/\bDRY RUN\b/.test(text)) {
      item.state = 'dry_run';
      item.detail = '';
    } else if (/FAILED, NOTHING WRITTEN:\s*/.test(text)) {
      item.state = 'failed';
      var failedAt = text.indexOf('FAILED, NOTHING WRITTEN:');
      item.detail = text.slice(failedAt + 25).trim().slice(0, 240);
    } else if (/NOTHING TO WRITE\b/.test(text)) {
      item.state = 'nothing';
      item.detail = '';
    } else if (/ERROR in /.test(text)) {
      item.detail = text.slice(text.indexOf('ERROR in '), 240);
    }
    if (item.state !== 'running' && item.state !== 'queued') {
      delete item.trail;
    }
    if (item.state !== 'running' || /ERROR in /.test(text)) {
      item.stepAt = now;
    }
    var dayKeys = Object.keys(status.days || {});
    var active = dayKeys.some(function (key) {
      return status.days[key].state === 'running' ||
        status.days[key].state === 'queued';
    });
    if (dayKeys.length && !active) {
      var failed = dayKeys.some(function (key) {
        return status.days[key].state === 'failed';
      });
      status.state = failed ? 'failed' : 'quiet';
      status.finishedAt = now;
    }
  }
  glob.set(KEY, status);
}
return msg;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'sih-hull';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
